// Introspect StudentBean
import java.beans.*;public class Q08 {public static class StudentBean {private int id;private String name;private double grade;public StudentBean(){}public int getId(){return id;}public void setId(int n){id=n;}public String getName(){return name;}public void setName(String n){name=n;}public double getGrade(){return grade;}public void setGrade(double g){grade=g;}}public static void main(String[] args)throws Exception{BeanInfo info=Introspector.getBeanInfo(StudentBean.class,Object.class);for(PropertyDescriptor p:info.getPropertyDescriptors())System.out.println("Property: "+p.getName());for(java.beans.MethodDescriptor m:info.getMethodDescriptors())System.out.println("Method: "+m.getName());}}
